/* ============================================================
   Monta um e-mail por inscricao pendente.

   Aceita a fila em qualquer das tres formas que o n8n pode
   entregar, conforme a versao e a configuracao do no HTTP:
     - um item por elemento (o no dividiu o array)
     - um item unico cujo json E o array
     - um item unico com o array dentro de .data
   Sem isso o workflow quebra em silencio quando a versao do n8n
   muda de comportamento.

   O texto e montado aqui, e nao no no de e-mail, porque muda
   conforme o tipo da inscricao e expressao longa dentro do no de
   e-mail e ilegivel.
   ============================================================ */

const EVENTO  = 'Career Day – Alfa University Fair';
const QUANDO  = '22 de agosto de 2026, das 9h as 12h';
const ONDE    = 'Alfacem Global Academy · Americas — Av. das Americas, 6551, Barra da Tijuca, Rio de Janeiro';
const CHEGADA = 'O credenciamento abre as 8h50, no 3o andar.';

const linhas = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) linhas.push(...j);
  else if (j && Array.isArray(j.data)) linhas.push(...j.data);
  else if (j && j.id) linhas.push(j);
}

const esc = (t) => String(t == null ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return linhas.map((d) => {
  const counselor = d.tipo === 'counselor';

  const quem = counselor
    ? '<p style="margin:0 0 16px">Sua inscricao como <strong>College Counselor</strong> pela instituicao <strong>' + esc(d.instituicao) + '</strong> foi recebida.</p>'
    : '<p style="margin:0 0 16px">A inscricao de <strong>' + esc(d.aluno) + '</strong>' + (d.ano ? ' (' + esc(d.ano) + ')' : '') + ' foi recebida.</p>';

  const acomp = (d.acompanhantes && d.acompanhantes.length)
    ? '<p style="margin:0 0 16px">Acompanhantes inscritos: <strong>' + esc(d.acompanhantes.join(', ')) + '</strong>. Cada um recebera o proprio cracha.</p>'
    : '';

  const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#201e1d;line-height:1.6">'
    + '<p style="margin:0 0 4px;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#b02020">' + EVENTO + ' · 3a Edicao</p>'
    + '<h2 style="margin:0 0 20px;font-size:22px">Inscricao confirmada</h2>'
    + '<p style="margin:0 0 16px">Ola, ' + esc(d.destinatario) + '.</p>'
    + quem + acomp
    + '<div style="background:#fff2ef;border-left:5px solid #ec3013;padding:16px 18px;margin:0 0 20px">'
    +   '<p style="margin:0 0 10px"><strong>Quando:</strong> ' + QUANDO + '</p>'
    +   '<p style="margin:0 0 10px"><strong>Onde:</strong> ' + ONDE + '</p>'
    +   '<p style="margin:0"><strong>Chegada:</strong> ' + CHEGADA + '</p>'
    + '</div>'
    + '<h3 style="margin:0 0 8px;font-size:16px">Seu cracha</h3>'
    + '<p style="margin:0 0 16px">O cracha e entregue <strong>no dia do evento</strong>, no credenciamento. Nao e preciso imprimir nada.</p>'
    + '<p style="margin:0 0 20px">Cada cracha traz um <strong>QR code</strong>. E por ele que os representantes das universidades registram o contato durante a feira — basta apresenta-lo ao conversar com cada instituicao.</p>'
    + '<p style="margin:0 0 6px;font-size:14px;color:#605d5d">Protocolo desta inscricao: <strong>' + esc(d.protocolo) + '</strong></p>'
    + '<p style="margin:0;font-size:14px;color:#605d5d">Guarde este e-mail. Se precisar corrigir alguma informacao, responda a esta mensagem citando o protocolo.</p>'
    + '</div>';

  return { json: { id: d.id, destino: d.destino, assunto: 'Inscricao confirmada — ' + EVENTO, html: html } };
});
